    - Literal characters
    - '.' (matches any single character)
    - '*' (matches zero or more of the preceding element)
    - '+' (matches one or more of the preceding element)

    This implementation uses an iterative approach with a dynamic programming table to avoid deep recursion.
    """

    n, m = len(pattern), len(text)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 2][0]  # Handle '*' matching zero occurrences.

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if pattern[i - 1] == text[j - 1] or pattern[i - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[i - 1] == '*':
                dp[i][j] = dp[i - 2][j] or (dp[i][j - 1] and (text[j - 1] == pattern[i - 2] or pattern[i - 2] == '.'))
            elif pattern[i - 1] == '+':
                dp[i][j] = dp[i - 1][j] and (text[j - 1] == pattern[i - 2] or pattern[i - 2] == '.')

    return dp[n][m]

